// Turns parsed icons into the package's source text: the shared wrapper, one
// file per icon, and a barrel per entry point. Pure string building, no I/O.

const NOTICE = "// Based on Keyline Icons. Copyright (c) 2026 Keyline Icons. MIT License, see LICENSE."

/**
 * Every generated file starts with these two lines. They're `//` comments on
 * purpose: minifiers drop them, where a `/*!` or `@license` comment would ship
 * one copy of the notice per imported icon. The full license is in
 * packages/react/LICENSE.
 */
export const header = (source) =>
  `// Generated by scripts/generate.mjs from ${source}. Do not edit.\n${NOTICE}\n`

/**
 * kebab-case SVG attribute -> React prop name.
 *
 * An unmapped kebab-case name would be emitted as a string-keyed attribute,
 * which typechecks and which React drops at runtime with a warning. Upstream
 * shipped every duotone plate at full strength that way once, when
 * `fill-opacity` was missing here, so `reactName` refuses anything not listed.
 */
const CAMEL = {
  "fill-rule": "fillRule",
  "clip-rule": "clipRule",
  "stroke-width": "strokeWidth",
  "stroke-linecap": "strokeLinecap",
  "stroke-linejoin": "strokeLinejoin",
  "fill-opacity": "fillOpacity",
  "stroke-opacity": "strokeOpacity",
}

function reactName(attr) {
  if (CAMEL[attr]) return CAMEL[attr]
  if (attr.includes("-") || attr.includes(":"))
    throw new Error(`no React name for the SVG attribute "${attr}": add it to CAMEL in scripts/lib/emit.mjs`)
  return attr
}

/** Numbers become JSX expressions (`strokeWidth={2}`), everything else a string. */
function jsxValue(value) {
  if (/^-?\d+(\.\d+)?$/.test(value)) return `{${value}}`
  if (/["{}]/.test(value)) throw new Error(`unsafe attribute value: ${value}`)
  return `"${value}"`
}

const jsxAttrs = (pairs) => pairs.map(([key, value]) => ` ${reactName(key)}=${jsxValue(value)}`).join("")

/** `arrow-up-right` -> `ArrowUpRight`. */
export const pascal = (name) =>
  name
    .split("-")
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join("")

/** The two names each icon is exported under: `StarIcon` and its alias `Star`. */
export const exportNames = (name) => [`${pascal(name)}Icon`, pascal(name)]

function renderDrawing({ root, elements }, indent) {
  const pad = " ".repeat(indent)
  const body = elements.map(({ tag, attrs }) => `${pad}  <${tag}${jsxAttrs(attrs)} />`).join("\n")
  return `${pad}<Icon${jsxAttrs(root)} {...props}>\n${body}\n${pad}</Icon>`
}

/**
 * Groups variants that draw exactly the same thing, so a fill that is a copy
 * of the outline (552 rounded icons) is written once. The outline's group
 * comes first; it becomes the fallthrough, which is what makes it the default.
 */
function groupVariants(drawings) {
  const groups = new Map()
  for (const [variant, drawing] of Object.entries(drawings)) {
    const key = JSON.stringify(drawing)
    const group = groups.get(key) ?? { drawing, variants: [] }
    groups.set(key, { ...group, variants: [...group.variants, variant] })
  }
  return [...groups.values()]
}

/** One icon's module: a function that picks its drawing by `variant`. */
export function emitIconFile({ name, drawings }, { source, wrapperImport }) {
  const [component, alias] = exportNames(name)
  const [outline, ...others] = groupVariants(drawings)
  const branches = others.map(({ drawing, variants }) => {
    const test = variants.map((v) => `variant === "${v}"`).join(" || ")
    return `  if (${test}) {\n    return (\n${renderDrawing(drawing, 6)}\n    )\n  }\n`
  })
  const params = others.length ? "{ variant, ...props }" : "{ variant: _variant, ...props }"
  return (
    `${header(source)}\n` +
    `import { Icon, type IconProps } from "${wrapperImport}"\n\n` +
    `export function ${component}(${params}: IconProps) {\n` +
    branches.join("") +
    `  return (\n${renderDrawing(outline.drawing, 4)}\n  )\n}\n\n` +
    `export { ${component} as ${alias} }\n`
  )
}

/** An entry point's index: every icon's two names, plus the prop types. */
export function emitBarrel(names, { source, wrapperImport }) {
  const lines = names.map((name) => `export { ${exportNames(name).join(", ")} } from "./icons/${name}.js"`)
  return (
    `${header(source)}\n` +
    `export type { IconProps, IconVariant } from "${wrapperImport}"\n\n` +
    `${lines.join("\n")}\n`
  )
}

/**
 * The <svg> every icon renders. Each icon passes its own presentation
 * attributes (a fill-only drawing carries no stroke, and forcing one on would
 * outline its knockouts), then the caller's props, so every default here and
 * in the icon can be overridden, `aria-hidden` included.
 */
export function emitWrapper() {
  return `${header("the template in scripts/lib/emit.mjs")}
import type { SVGProps } from "react"

/** Which drawing an icon renders. */
export type IconVariant = "outline" | "fill" | "duotone"

export type IconProps = Omit<SVGProps<SVGSVGElement>, "children"> & {
  /** Which drawing to render. Defaults to \`"outline"\`. */
  variant?: IconVariant
}

/** A 24px grid in \`currentColor\`, hidden from assistive technology unless told otherwise. */
export function Icon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={24}
      height={24}
      aria-hidden="true"
      focusable="false"
      {...props}
    />
  )
}
`
}
